RRB.load({"id": "gd-full-3", "exam": "gd", "label": "Group D full mock 3 (100 Q)", "questions": [{"s": "General Science", "t": "Chemistry", "q": "Chlorine has atomic number 17. How many electrons are in its outermost shell?", "o": ["8", "7", "1", "17"], "a": 1, "e": "Electronic configuration 2, 8, 7 → 7 valence electrons.", "qh": "क्लोरीन का परमाणु क्रमांक 17 है। उसके सबसे बाहरी कोश में कितने इलेक्ट्रॉन हैं?", "oh": ["8", "7", "1", "17"], "eh": "इलेक्ट्रॉनिक विन्यास 2, 8, 7 → बाहरी कोश में 7 इलेक्ट्रॉन।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "In which medium does sound travel the fastest?", "o": ["Steel", "Water", "Air", "Vacuum"], "a": 0, "e": "Sound travels fastest in solids such as steel, slower in liquids and slowest in gases; it cannot travel in vacuum.", "qh": "ध्वनि किस माध्यम में सबसे तेज़ चलती है?", "oh": ["स्टील", "पानी", "हवा", "निर्वात"], "eh": "ध्वनि ठोस (जैसे स्टील) में सबसे तेज़, द्रव में कम और गैस में सबसे धीमी चलती है; निर्वात में चलती ही नहीं।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "What is the chemical formula of quicklime?", "o": ["CaCO₃", "CaO", "Ca(OH)₂", "CaCl₂"], "a": 1, "e": "Quicklime is calcium oxide, CaO; slaked lime is Ca(OH)₂.", "qh": "बिना बुझे चूने (क्विकलाइम) का रासायनिक सूत्र क्या है?", "oh": ["CaCO₃", "CaO", "Ca(OH)₂", "CaCl₂"], "eh": "बिना बुझा चूना कैल्शियम ऑक्साइड (CaO) है; बुझा चूना Ca(OH)₂ है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "What is the chemical symbol of sodium?", "o": ["S", "So", "Na", "Sd"], "a": 2, "e": "Sodium's symbol Na comes from its Latin name 'natrium'.", "qh": "सोडियम का रासायनिक प्रतीक क्या है?", "oh": ["S", "So", "Na", "Sd"], "eh": "सोडियम का प्रतीक Na उसके लैटिन नाम 'नैट्रियम' से आता है।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "How much work is done in lifting a 10 kg box vertically through 3 m? (g = 10 m/s²)", "o": ["30 J", "3000 J", "130 J", "300 J"], "a": 3, "e": "W = mgh = 10 × 10 × 3 = 300 J.", "qh": "10 kg के एक डिब्बे को 3 m सीधा ऊपर उठाने में कितना कार्य होता है? (g = 10 m/s²)", "oh": ["30 J", "3000 J", "130 J", "300 J"], "eh": "W = mgh = 10 × 10 × 3 = 300 J।", "level": "tough"}, {"s": "General Science", "t": "Chemistry", "q": "What is the valency of nitrogen in ammonia (NH₃)?", "o": ["1", "5", "3", "4"], "a": 2, "e": "Nitrogen forms three bonds with three hydrogen atoms, so its valency is 3.", "qh": "अमोनिया (NH₃) में नाइट्रोजन की संयोजकता कितनी है?", "oh": ["1", "5", "3", "4"], "eh": "नाइट्रोजन तीन हाइड्रोजन परमाणुओं से तीन बंध बनाता है, इसलिए संयोजकता 3 है।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "A train covers 360 km in 4 hours. What is its average speed in m/s?", "o": ["90 m/s", "15 m/s", "25 m/s", "36 m/s"], "a": 2, "e": "360/4 = 90 km/h = 90 × 5/18 = 25 m/s.", "qh": "एक ट्रेन 4 घंटे में 360 km चलती है। उसकी औसत चाल m/s में कितनी है?", "oh": ["90 m/s", "15 m/s", "25 m/s", "36 m/s"], "eh": "360/4 = 90 km/h = 90 × 5/18 = 25 m/s।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "In adults, red blood cells are mainly produced in the:", "o": ["Bone marrow", "Liver", "Spleen", "Heart"], "a": 0, "e": "Red bone marrow produces red blood cells in adults.", "qh": "वयस्कों में लाल रक्त कोशिकाएँ मुख्य रूप से कहाँ बनती हैं?", "oh": ["अस्थि मज्जा (बोन मैरो)", "यकृत", "तिल्ली", "हृदय"], "eh": "वयस्कों में लाल अस्थि मज्जा लाल रक्त कोशिकाएँ बनाती है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "A current of 2 A flows through a wire for 5 minutes. How much charge passes through it?", "o": ["600 C", "10 C", "300 C", "150 C"], "a": 0, "e": "Q = I × t = 2 A × (5 × 60) s = 600 coulomb.", "qh": "किसी तार में 5 मिनट तक 2 A धारा बहती है। उसमें से कितना आवेश गुज़रता है?", "oh": ["600 C", "10 C", "300 C", "150 C"], "eh": "Q = I × t = 2 A × (5 × 60) s = 600 कूलॉम।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Which device changes mechanical energy into electrical energy?", "o": ["Electric motor", "Transformer", "Electric generator", "Electric fan"], "a": 2, "e": "A generator (dynamo) converts mechanical energy into electrical energy; a motor does the opposite.", "qh": "कौन-सा उपकरण यांत्रिक ऊर्जा को विद्युत ऊर्जा में बदलता है?", "oh": ["विद्युत मोटर", "ट्रांसफ़ॉर्मर", "विद्युत जनित्र (जनरेटर)", "बिजली का पंखा"], "eh": "जनरेटर (डायनेमो) यांत्रिक ऊर्जा को बिजली में बदलता है; मोटर इसका उलटा करती है।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "How much heat is needed to raise the temperature of 2 kg of water by 5 °C? (specific heat of water = 4200 J/kg °C)", "o": ["21,000 J", "8,400 J", "4,200 J", "42,000 J"], "a": 3, "e": "Q = mcΔT = 2 × 4200 × 5 = 42,000 J.", "qh": "2 kg पानी का तापमान 5 °C बढ़ाने के लिए कितनी ऊष्मा चाहिए? (पानी की विशिष्ट ऊष्मा = 4200 J/kg °C)", "oh": ["21,000 J", "8,400 J", "4,200 J", "42,000 J"], "eh": "Q = mcΔT = 2 × 4200 × 5 = 42,000 J।", "level": "tough"}, {"s": "General Science", "t": "Biology", "q": "Scurvy is caused by the deficiency of:", "o": ["Vitamin A", "Vitamin D", "Vitamin B₁", "Vitamin C"], "a": 3, "e": "Lack of vitamin C causes scurvy (bleeding gums).", "qh": "स्कर्वी रोग किसकी कमी से होता है?", "oh": ["विटामिन A", "विटामिन D", "विटामिन B₁", "विटामिन C"], "eh": "विटामिन C की कमी से स्कर्वी (मसूड़ों से खून) होता है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Where in the cell does protein synthesis take place?", "o": ["Lysosomes", "Ribosomes", "Centrosome", "Vacuoles"], "a": 1, "e": "Ribosomes read mRNA and join amino acids to make proteins.", "qh": "कोशिका में प्रोटीन संश्लेषण कहाँ होता है?", "oh": ["लाइसोसोम", "राइबोसोम", "तारककाय (सेंट्रोसोम)", "रिक्तिकाएँ"], "eh": "राइबोसोम mRNA पढ़कर अमीनो अम्लों को जोड़ते हैं और प्रोटीन बनाते हैं।", "level": "tough"}, {"s": "General Science", "t": "Biology", "q": "How many bones are there in the body of an adult human?", "o": ["206", "212", "300", "186"], "a": 0, "e": "An adult human skeleton has 206 bones (a newborn has about 300).", "qh": "एक वयस्क इंसान के शरीर में कितनी हड्डियाँ होती हैं?", "oh": ["206", "212", "300", "186"], "eh": "वयस्क के कंकाल में 206 हड्डियाँ होती हैं (नवजात में लगभग 300)।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "By surface area and weight, the largest organ of the human body is the:", "o": ["Liver", "Skin", "Brain", "Lungs"], "a": 1, "e": "The skin is the largest organ by area and weight.", "qh": "मानव शरीर का सबसे बड़ा अंग कौन-सा है?", "oh": ["यकृत", "त्वचा", "मस्तिष्क", "फेफड़े"], "eh": "क्षेत्रफल और वज़न में त्वचा सबसे बड़ा अंग है।", "level": "easy"}, {"s": "General Science", "t": "Biology", "q": "Which gland is called the 'master gland' of the body?", "o": ["Thyroid", "Pituitary", "Adrenal", "Pancreas"], "a": 1, "e": "The pituitary controls many other endocrine glands, so it is called the master gland.", "qh": "किस ग्रंथि को शरीर की 'मास्टर ग्रंथि' कहते हैं?", "oh": ["थायरॉइड", "पीयूष ग्रंथि (पिट्यूटरी)", "अधिवृक्क (एड्रिनल)", "अग्न्याशय"], "eh": "पिट्यूटरी कई दूसरी ग्रंथियों को नियंत्रित करती है, इसलिए इसे मास्टर ग्रंथि कहते हैं।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Which type of mirror is used as a rear-view mirror in vehicles?", "o": ["Concave mirror", "Plane mirror", "Convex mirror", "Cylindrical mirror"], "a": 2, "e": "A convex mirror gives an erect, smaller image and a wider field of view.", "qh": "गाड़ियों में पीछे देखने के लिए किस प्रकार का दर्पण लगाया जाता है?", "oh": ["अवतल दर्पण", "समतल दर्पण", "उत्तल दर्पण", "बेलनाकार दर्पण"], "eh": "उत्तल दर्पण सीधा, छोटा प्रतिबिंब बनाता है और बड़ा इलाका दिखाता है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Which plant hormone mainly promotes cell division?", "o": ["Abscisic acid", "Ethylene", "Cytokinin", "Auxin"], "a": 2, "e": "Cytokinins promote cell division; abscisic acid slows growth, ethylene helps ripening and auxin causes cell elongation.", "qh": "कौन-सा पादप हॉर्मोन मुख्य रूप से कोशिका विभाजन बढ़ाता है?", "oh": ["ऐब्सिसिक अम्ल", "एथिलीन", "साइटोकाइनिन", "ऑक्सिन"], "eh": "साइटोकाइनिन कोशिका विभाजन बढ़ाता है; ऐब्सिसिक अम्ल वृद्धि रोकता है, एथिलीन फल पकाता है और ऑक्सिन कोशिका को लंबा करता है।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "1 newton is the force that gives a mass of 1 kg an acceleration of:", "o": ["1 m/s", "9.8 m/s²", "10 m/s²", "1 m/s²"], "a": 3, "e": "F = ma, so 1 N = 1 kg × 1 m/s².", "qh": "1 न्यूटन वह बल है जो 1 kg द्रव्यमान को कितना त्वरण देता है?", "oh": ["1 m/s", "9.8 m/s²", "10 m/s²", "1 m/s²"], "eh": "F = ma, इसलिए 1 N = 1 kg × 1 m/s²।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "A bulb works on 220 V and draws a current of 0.5 A. What is its power?", "o": ["440 W", "110 W", "220.5 W", "44 W"], "a": 1, "e": "P = VI = 220 × 0.5 = 110 W.", "qh": "एक बल्ब 220 V पर चलता है और 0.5 A धारा लेता है। उसकी शक्ति कितनी है?", "oh": ["440 W", "110 W", "220.5 W", "44 W"], "eh": "P = VI = 220 × 0.5 = 110 W।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Which gas turns lime water milky?", "o": ["Oxygen", "Hydrogen", "Carbon dioxide", "Nitrogen"], "a": 2, "e": "CO₂ reacts with lime water, Ca(OH)₂, to form insoluble calcium carbonate, which makes it milky.", "qh": "कौन-सी गैस चूने के पानी को दूधिया कर देती है?", "oh": ["ऑक्सीजन", "हाइड्रोजन", "कार्बन डाइऑक्साइड", "नाइट्रोजन"], "eh": "CO₂ चूने के पानी Ca(OH)₂ से मिलकर न घुलने वाला कैल्शियम कार्बोनेट बनाती है, जिससे पानी दूधिया हो जाता है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Which gas is mainly responsible for the greenhouse effect?", "o": ["Carbon dioxide", "Oxygen", "Nitrogen", "Argon"], "a": 0, "e": "Carbon dioxide traps heat radiated by the Earth and is the main greenhouse gas from human activity.", "qh": "ग्रीनहाउस प्रभाव के लिए मुख्य रूप से कौन-सी गैस ज़िम्मेदार है?", "oh": ["कार्बन डाइऑक्साइड", "ऑक्सीजन", "नाइट्रोजन", "आर्गन"], "eh": "कार्बन डाइऑक्साइड धरती से निकलने वाली गर्मी को रोकती है और इंसानी गतिविधियों से निकलने वाली मुख्य ग्रीनहाउस गैस है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Which metal is a liquid at room temperature?", "o": ["Sodium", "Mercury", "Aluminium", "Zinc"], "a": 1, "e": "Mercury is the only metal that is liquid at ordinary room temperature.", "qh": "कौन-सी धातु कमरे के तापमान पर द्रव होती है?", "oh": ["सोडियम", "पारा (मरकरी)", "एल्युमिनियम", "ज़िंक"], "eh": "पारा ही ऐसी धातु है जो सामान्य कमरे के तापमान पर द्रव रहती है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Which acid is found in lemon?", "o": ["Acetic acid", "Tartaric acid", "Citric acid", "Oxalic acid"], "a": 2, "e": "Lemons and oranges contain citric acid.", "qh": "नींबू में कौन-सा अम्ल पाया जाता है?", "oh": ["ऐसिटिक अम्ल", "टार्टरिक अम्ल", "साइट्रिक अम्ल", "ऑक्ज़ैलिक अम्ल"], "eh": "नींबू और संतरे में साइट्रिक अम्ल होता है।", "level": "easy"}, {"s": "General Science", "t": "Biology", "q": "Which blood vessels carry blood away from the heart?", "o": ["Veins", "Arteries", "Capillaries", "Lymph vessels"], "a": 1, "e": "Arteries carry blood away from the heart; veins bring it back.", "qh": "कौन-सी रक्त वाहिकाएँ खून को हृदय से दूर ले जाती हैं?", "oh": ["शिराएँ", "धमनियाँ", "केशिकाएँ", "लसीका वाहिकाएँ"], "eh": "धमनियाँ खून को हृदय से दूर ले जाती हैं; शिराएँ वापस लाती हैं।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "What is the mean proportional between 8 and 18?", "o": ["9", "14", "24", "12"], "a": 3, "e": "√(8 × 18) = √144 = 12.", "qh": "8 और 18 का मध्यानुपाती क्या है?", "oh": ["9", "14", "24", "12"], "eh": "√(8 × 18) = √144 = 12।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "An amount is divided among Priya, Neha and Rekha in the ratio 3 : 5 : 7. If Rekha gets ₹800 more than Priya, what is Neha's share?", "o": ["₹2,000", "₹600", "₹1,200", "₹1,000"], "a": 3, "e": "(7 − 3) parts = ₹800 → 1 part = ₹200; Neha = 5 × ₹200 = ₹1,000.", "qh": "एक रकम को प्रिया, नेहा और रेखा में 3 : 5 : 7 के अनुपात में बाँटा गया। अगर रेखा को प्रिया से ₹800 ज़्यादा मिलते हैं, तो नेहा का हिस्सा कितना है?", "oh": ["₹2,000", "₹600", "₹1,200", "₹1,000"], "eh": "(7 − 3) भाग = ₹800 → 1 भाग = ₹200; नेहा = 5 × ₹200 = ₹1,000।", "level": "medium"}, {"s": "Mathematics", "t": "Mensuration", "q": "The edge of a cube is 6 cm. What is its total surface area?", "o": ["144 cm²", "216 cm²", "72 cm²", "222 cm²"], "a": 1, "e": "6a² = 6 × 6² = 216 cm².", "qh": "एक घन की भुजा 6 cm है। उसका कुल पृष्ठीय क्षेत्रफल कितना है?", "oh": ["144 cm²", "216 cm²", "72 cm²", "222 cm²"], "eh": "6a² = 6 × 6² = 216 cm²।", "level": "easy"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "What is the mode of: 58, 22, 36, 36, 30, 23, 50, 36, 14, 25, 18?", "o": ["30", "36", "58", "14"], "a": 1, "e": "36 occurs most often (3 times), so mode = 36.", "qh": "58, 22, 36, 36, 30, 23, 50, 36, 14, 25, 18 का बहुलक क्या है?", "oh": ["30", "36", "58", "14"], "eh": "36 सबसे ज़्यादा बार (3 बार) आता है, इसलिए बहुलक = 36।", "level": "medium"}, {"s": "Mathematics", "t": "Geometry", "q": "How many diagonals does a polygon with 9 sides have?", "o": ["24", "36", "27", "31.5"], "a": 2, "e": "Diagonals = n(n − 3)/2 = 9×6/2 = 27.", "qh": "9 भुजाओं वाले बहुभुज में कितने विकर्ण होते हैं?", "oh": ["24", "36", "27", "31.5"], "eh": "विकर्ण = n(n − 3)/2 = 9×6/2 = 27।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "Suresh and Deepak can finish a work in 15 days and 10 days respectively. They work together for 3 days and then Suresh leaves. In how many days in total will the work be finished?", "o": ["8 days", "7 days", "5 days", "9 days"], "a": 0, "e": "In 3 days: 3 × (1/15 + 1/10) = 0.5 done. Left 0.5 is done by Deepak in 5 days. Total = 8 days.", "qh": "सुरेश और दीपक एक काम क्रमशः 15 दिन और 10 दिन में पूरा कर सकते हैं। दोनों 3 दिन साथ काम करते हैं और फिर सुरेश काम छोड़ देता है। काम कुल कितने दिन में पूरा होगा?", "oh": ["8 दिन", "7 दिन", "5 दिन", "9 दिन"], "eh": "3 दिन में: 3 × (1/15 + 1/10) = 0.5 काम हुआ। बचा 0.5 काम अकेले दीपक से 5 दिन में होता है। कुल = 8 दिन।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "How many numbers from 200 to 600 are divisible by 3 or 5 (or both)?", "o": ["188", "189", "376", "187"], "a": 0, "e": "By 3: 134, by 5: 81, by both (LCM 15): 27. Total = 134 + 81 − 27 = 188.", "qh": "200 से 600 तक कितनी संख्याएँ 3 या 5 (या दोनों) से विभाज्य हैं?", "oh": ["188", "189", "376", "187"], "eh": "3: 134, 5: 81, दोनों से (LCM 15): 27. कुल = 134 + 81 − 27 = 188।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A dishonest grocer uses a weight of 950 g in place of 1 kg but claims to sell at cost price. What is his gain percentage?", "o": ["4 5/19%", "5%", "6 5/19%", "5 5/19%"], "a": 3, "e": "He gives 950 g but charges for 1000 g: gain = 1000 × 1/950 − 1 = 5 5/19%.", "qh": "एक बेईमान दुकानदार 1 kg की जगह 950 g का बाट इस्तेमाल करता है पर दावा करता है कि वह क्रय मूल्य पर ही बेचता है। उसका लाभ प्रतिशत क्या है?", "oh": ["4 5/19%", "5%", "6 5/19%", "5 5/19%"], "eh": "वह 950 g देता है पर 1000 g के पैसे लेता है: लाभ = 1000 × 1/950 − 1 = 5 5/19%।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "The price of an article is first increased by 20% and then decreased by 30%. What is the net percentage change in its price?", "o": ["16% decrease", "6% decrease", "14% decrease", "16% increase"], "a": 0, "e": "Net factor = 1.2 × 0.7 = 0.84. Change = -16%.", "qh": "किसी वस्तु का दाम पहले 20% बढ़ाया जाता है और फिर 30% घटाया जाता है। दाम में कुल कितने प्रतिशत का बदलाव हुआ?", "oh": ["16% कमी", "6% कमी", "14% कमी", "16% बढ़ोतरी"], "eh": "कुल गुणक = 1.2 × 0.7 = 0.84। बदलाव = -16%।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A car covers 240 km in 3 hours 20 minutes. What is its speed in metres per second?", "o": ["20 m/s", "25 m/s", "40 m/s", "259.2 m/s"], "a": 0, "e": "Speed = 240/10/3 = 72 km/h = 72 × 5/18 = 20 m/s.", "qh": "एक कार 240 km की दूरी 3 घंटे 20 मिनट में तय करती है। उसकी रफ़्तार मीटर प्रति सेकंड में कितनी है?", "oh": ["20 m/s", "25 m/s", "40 m/s", "259.2 m/s"], "eh": "रफ़्तार = 240/10/3 = 72 km/h = 72 × 5/18 = 20 m/s।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "Anjali's salary is 40% more than Meena's salary. By what percentage is Meena's salary less than Anjali's?", "o": ["20%", "60%", "28 4/7%", "33 4/7%"], "a": 2, "e": "Take Meena = 100, Anjali = 140. Less by 40/140 × 100 = 28 4/7%.", "qh": "अंजलि की तनख्वाह मीना की तनख्वाह से 40% ज़्यादा है। मीना की तनख्वाह अंजलि की तनख्वाह से कितने प्रतिशत कम है?", "oh": ["20%", "60%", "28 4/7%", "33 4/7%"], "eh": "मीना = 100 मानें, अंजलि = 140। कम = 40/140 × 100 = 28 4/7%।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A vendor buys 20 bananas for ₹50 and sells 16 bananas for ₹60. What is his profit percentage?", "o": ["50%", "55%", "100%", "20%"], "a": 0, "e": "CP of 1 = 2.5, SP of 1 = 3.75. Profit % = |3.75 − 2.5|/2.5 × 100 = 50%.", "qh": "एक विक्रेता ₹50 में 20 केले खरीदता है और ₹60 में 16 केले बेचता है। उसका लाभ प्रतिशत क्या है?", "oh": ["50%", "55%", "100%", "20%"], "eh": "1 केले का क्रय मूल्य = 2.5, विक्रय मूल्य = 3.75। प्रतिशत = |3.75 − 2.5|/2.5 × 100 = 50%।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "If the number 8*3792 is divisible by 11, what is the digit in place of *?", "o": ["1", "0", "3", "8"], "a": 1, "e": "Rule: difference of alternate digit sums divisible by 11. Only * = 0 works: 803792 ÷ 11 = 73072.", "qh": "अगर संख्या 8*3792 पूरी तरह 11 से विभाज्य है, तो * की जगह कौन-सा अंक है?", "oh": ["1", "0", "3", "8"], "eh": "नियम: एक छोड़कर अंकों के योगों का अंतर 11 से विभाज्य। केवल * = 0 सही बैठता है: 803792 ÷ 11 = 73072।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "Pipes A and B can fill a tank in 24 hours and 40 hours, while pipe C can empty the full tank in 30 hours. If all three are opened together on an empty tank, in how many hours will it be full?", "o": ["32 hours", "60 hours", "17 hours", "30 hours"], "a": 3, "e": "Net per hour = 1/24 + 1/40 − 1/30 = 1/30 → 30 hours.", "qh": "पाइप A और B एक टंकी को 24 घंटे और 40 घंटे में भरते हैं, जबकि पाइप C भरी टंकी को 30 घंटे में खाली करता है। खाली टंकी पर तीनों एक साथ खोलने पर टंकी कितने घंटे में भरेगी?", "oh": ["32 घंटे", "60 घंटे", "17 घंटे", "30 घंटे"], "eh": "हर घंटे कुल भराई = 1/24 + 1/40 − 1/30 = 1/30 → 30 घंटे।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "A batsman has a certain average after 10 innings. In the 11th innings he scores 65 runs, which raises his average by 3. What is his new average?", "o": ["35", "38", "32", "36"], "a": 0, "e": "Let old average = x. 10x + 65 = 11(x + 3) → x = 65 − 33 = 32. New average = 35.", "qh": "10 पारियों के बाद एक बल्लेबाज़ का कोई औसत है। 11वीं पारी में वह 65 रन बनाता है, जिससे उसका औसत 3 बढ़ जाता है। उसका नया औसत क्या है?", "oh": ["35", "38", "32", "36"], "eh": "पुराना औसत = x। 10x + 65 = 11(x + 3) → x = 65 − 33 = 32। नया औसत = 35।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "If a + b + c = 0, what is the value of (a³ + b³ + c³)/(abc)?", "o": ["0", "3", "1", "−3"], "a": 1, "e": "If a + b + c = 0, then a³ + b³ + c³ = 3abc, so the value is 3.", "qh": "अगर a + b + c = 0 है, तो (a³ + b³ + c³)/(abc) का मान क्या है?", "oh": ["0", "3", "1", "−3"], "eh": "अगर a + b + c = 0 हो, तो a³ + b³ + c³ = 3abc, इसलिए मान 3 है।", "level": "tough"}, {"s": "Mathematics", "t": "Interest", "q": "The difference between compound interest and simple interest on a sum for 2 years at 4% per annum is ₹20. What is the sum?", "o": ["₹12,500", "₹25,000", "₹11,500", "₹14,500"], "a": 0, "e": "CI − SI = P[(1 + 4/100)^2 − 1 − 2 × 4/100] = 1/625 × P = ₹20 → P = ₹12,500.", "qh": "किसी रकम पर 4% वार्षिक दर से 2 साल के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹20 है। रकम कितनी है?", "oh": ["₹12,500", "₹25,000", "₹11,500", "₹14,500"], "eh": "CI − SI = P[(1 + 4/100)^2 − 1 − 2 × 4/100] = 1/625 × P = ₹20 → P = ₹12,500।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Two chairs are sold for ₹990 each. On one there is a gain of 20% and on the other a loss of 20%. What is the overall gain or loss percentage?", "o": ["8% loss", "4% loss", "4% gain", "No profit, no loss"], "a": 1, "e": "When SP is the same and gain% = loss% = 20, there is always a loss of x²/100 = 400/100 = 4%.", "qh": "दो कुर्सियाँ ₹990 प्रत्येक में बेचे गए। एक पर 20% लाभ और दूसरे पर 20% हानि हुई। कुल मिलाकर कितने प्रतिशत लाभ या हानि हुई?", "oh": ["8% हानि", "4% हानि", "4% लाभ", "न लाभ, न हानि"], "eh": "जब विक्रय मूल्य बराबर हो और लाभ% = हानि% = 20, तो हमेशा x²/100 = 400/100 = 4% हानि होती है।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 4 2/3 × 3 1/2 ÷ 1 1/2", "o": ["95/9", "196/9", "9/98", "98/9"], "a": 3, "e": "Convert to improper fractions: 14/3, 7/2, 3/2. Working step by step gives 98/9.", "qh": "सरल कीजिए: 4 2/3 × 3 1/2 ÷ 1 1/2", "oh": ["95/9", "196/9", "9/98", "98/9"], "eh": "मिश्र भिन्नों को साधारण भिन्न में बदलें: 14/3, 7/2, 3/2। क्रम से हल करने पर 98/9।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "A bag contains ₹1, 50-paise and 25-paise coins in the ratio 2 : 3 : 4. If the total value is ₹90, how many 50-paise coins are there?", "o": ["120", "40", "60", "80"], "a": 2, "e": "Value of one set (2, 3, 4 coins) = 2 × 1 + 3 × ½ + 4 × ¼ = ₹4.5. Sets = 90 ÷ 4.5 = 20; 50-paise coins = 3 × 20 = 60.", "qh": "एक थैली में ₹1, 50 पैसे और 25 पैसे के सिक्के 2 : 3 : 4 के अनुपात में हैं। अगर कुल रकम ₹90 है, तो 50 पैसे के कितने सिक्के हैं?", "oh": ["120", "40", "60", "80"], "eh": "एक सेट (2, 3, 4 सिक्के) की कीमत = 2 × 1 + 3 × ½ + 4 × ¼ = ₹4.5। सेट = 90 ÷ 4.5 = 20; 50 पैसे के सिक्के = 3 × 20 = 60।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the area of a triangle whose sides are 17 cm, 25 cm and 28 cm?", "o": ["222 cm²", "420 cm²", "105 cm²", "210 cm²"], "a": 3, "e": "s = (17+25+28)/2 = 35. Area = √[s(s−a)(s−b)(s−c)] = √(35×18×10×7) = 210 cm².", "qh": "उस त्रिभुज का क्षेत्रफल कितना है जिसकी भुजाएँ 17 cm, 25 cm और 28 cm हैं?", "oh": ["222 cm²", "420 cm²", "105 cm²", "210 cm²"], "eh": "s = (17+25+28)/2 = 35. क्षेत्रफल = √[s(s−a)(s−b)(s−c)] = √(35×18×10×7) = 210 cm²।", "level": "medium"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If sin θ = 20/29, what is the value of cos²θ − sin²θ? (θ is acute)", "o": ["441/841", "1", "41/841", "1/29"], "a": 2, "e": "cos θ = 21/29. cos²θ − sin²θ = (441 − 400)/841 = 41/841.", "qh": "अगर sin θ = 20/29 है, तो cos²θ − sin²θ का मान क्या है? (θ न्यून कोण है)", "oh": ["441/841", "1", "41/841", "1/29"], "eh": "cos θ = 21/29. cos²θ − sin²θ = (441 − 400)/841 = 41/841।", "level": "tough"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "Travelling at 40 km/h, a man reaches his office 6 minutes late. Travelling at 50 km/h, he reaches 6 minutes early. What is the distance to his office?", "o": ["45 km", "20 km", "80 km", "40 km"], "a": 3, "e": "D/40 − D/50 = (6 + 6)/60 h → D = 40 × 50/10 × 12/60 = 40 km.", "qh": "40 km/h की रफ़्तार से चलकर एक आदमी दफ़्तर 6 मिनट देर से पहुँचता है। 50 km/h की रफ़्तार से चलकर वह 6 मिनट पहले पहुँचता है। दफ़्तर कितनी दूर है?", "oh": ["45 km", "20 km", "80 km", "40 km"], "eh": "D/40 − D/50 = (6 + 6)/60 h → D = 40 × 50/10 × 12/60 = 40 km।", "level": "tough"}, {"s": "Mathematics", "t": "Ages", "q": "A mother is 4 times as old as her daughter. After 6 years, she will be 3 times as old as her daughter. What is the mother's present age?", "o": ["54 years", "12 years", "48 years", "60 years"], "a": 2, "e": "4d + 6 = 3(d + 6) → d = 12; mother = 4 × 12 = 48 years.", "qh": "एक माँ की आयु उसकी बेटी की आयु की 4 गुनी है। 6 साल बाद वह बेटी की आयु की 3 गुनी होगी। माँ की अभी की आयु कितनी है?", "oh": ["54 साल", "12 साल", "48 साल", "60 साल"], "eh": "4d + 6 = 3(d + 6) → d = 12; माँ = 4 × 12 = 48 साल।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 261 ÷ 29 × 25 + 3 − 16", "o": ["424", "222", "209", "212"], "a": 3, "e": "Follow BODMAS (brackets, then ÷ and × from left to right, then + and −): value = 212.", "qh": "सरल कीजिए: 261 ÷ 29 × 25 + 3 − 16", "oh": ["424", "222", "209", "212"], "eh": "BODMAS के नियम से (पहले कोष्ठक, फिर बाएँ से दाएँ ÷ और ×, फिर + और −): मान = 212।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Mirror Image", "q": "Which of the following words has all its letters looking the same in a mirror image (mirror placed to the right)? (Capital letters.)", "o": ["WAIT", "COOKED", "OXIDE", "CHECK"], "a": 0, "e": "In a side mirror, letters A, H, I, M, O, T, U, V, W, X, Y look the same. Every letter of WAIT is from this group.", "qh": "नीचे दिए शब्दों में से किस शब्द के सभी अक्षर दर्पण प्रतिबिंब (दर्पण दाईं ओर रखा हो) में वैसे ही दिखेंगे? (बड़े अंग्रेज़ी अक्षर।)", "oh": ["WAIT", "COOKED", "OXIDE", "CHECK"], "eh": "बगल के दर्पण में A, H, I, M, O, T, U, V, W, X, Y वैसे ही दिखते हैं। WAIT के सारे अक्षर इसी समूह के हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n3 7 1 2 1 1 2 7 7 2 3 3 5 1 8 3 6 1 7 9\nHow many times does 2 appear immediately followed by 1?", "o": ["4", "1", "2", "3"], "a": 1, "e": "Matching groups: 1 2 1 → 1.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n3 7 1 2 1 1 2 7 7 2 3 3 5 1 8 3 6 1 7 9\n2 के ठीक बाद 1 कितनी बार आता है?", "oh": ["4", "1", "2", "3"], "eh": "शर्त पूरी करने वाले समूह: 1 2 1 → 1।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nNPCN : OSEM :: LWHZ : ?", "o": ["YJZM", "KTFA", "MZJY", "MZJZ"], "a": 2, "e": "Each letter moves +1, +3, +2, -1 in order. LWHZ → MZJY.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nNPCN : OSEM :: LWHZ : ?", "oh": ["YJZM", "KTFA", "MZJY", "MZJZ"], "eh": "हर अक्षर क्रम से +1, +3, +2, -1 खिसकता है। LWHZ → MZJY।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Which letter is 9th from the left end of the English alphabet?", "o": ["J", "I", "H", "K"], "a": 1, "e": "Left 9th letter = I.", "qh": "अंग्रेज़ी वर्णमाला में बाएँ छोर से 9वाँ अक्षर कौन-सा है?", "oh": ["J", "I", "H", "K"], "eh": "बाएँ से 9वाँ अक्षर = I।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n36, 49, 62, 75, 88, 101, ?", "o": ["202", "116", "115", "114"], "a": 3, "e": "Rule: Add 13 each time. So ? = 114.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n36, 49, 62, 75, 88, 101, ?", "oh": ["202", "116", "115", "114"], "eh": "नियम: हर बार 13 जोड़ें। इसलिए ? = 114।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of students, Manoj is 14th from the left end and 8th from the right end. How many students are there in the row?", "o": ["21", "22", "23", "20"], "a": 0, "e": "Total = 14 + 8 − 1 = 21.", "qh": "छात्रों की एक पंक्ति में मनोज बाएँ छोर से 14वें और दाएँ छोर से 8वें स्थान पर है। पंक्ति में कितने छात्र हैं?", "oh": ["21", "22", "23", "20"], "eh": "कुल = 14 + 8 − 1 = 21।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "B, R, F, W and S are sitting in a row, all facing North.\nR sits immediately to the right of W.\nExactly 3 persons sit between R and S.\nR is an immediate neighbour of W.\nB and W sit next to each other.\nHow many persons sit between W and B?", "o": ["3", "1", "0", "2"], "a": 2, "e": "Only one order fits all clues (left to right): S F B W R. Answer: 0.", "qh": "B, R, F, W और S एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nR, W के ठीक दाईं ओर बैठा है।\nR और S के बीच ठीक 3 व्यक्ति बैठे हैं।\nR, W का ठीक पड़ोसी है।\nB और W पास-पास बैठे हैं।\nW और B के बीच कितने व्यक्ति बैठे हैं?", "oh": ["3", "1", "0", "2"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): S F B W R। उत्तर: 0।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "One morning, after sunrise, Rohit was standing facing a pole. The shadow of the pole fell exactly behind him. Which direction was Rohit facing?", "o": ["North", "South", "West", "East"], "a": 3, "e": "In the morning the Sun is in the East, so shadows fall towards the West. Shadow behind him → he faces East.", "qh": "एक दिन सुबह सूरज निकलने के बाद रोहित एक खंभे की ओर मुँह करके खड़ा था। खंभे की परछाईं ठीक उसके पीछे पड़ी। रोहित किस दिशा की ओर मुँह करके खड़ा था?", "oh": ["उत्तर", "दक्षिण", "पश्चिम", "पूर्व"], "eh": "सुबह को सूरज पूर्व में होता है, इसलिए परछाईं पश्चिम की ओर पड़ती है। परछाईं उसके पीछे → वह पूर्व की ओर देख रहा है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nSome bricks are pens.\nSome pens are not clocks.\nNo clocks are rivers.\nConclusions:\nI. Some rivers are clocks.\nII. All rivers are pens.", "o": ["Neither I nor II follows", "Only conclusion II follows", "Only conclusion I follows", "Both I and II follow"], "a": 0, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकुछ ईंटें पेन हैं।\nकुछ पेन घड़ियाँ नहीं हैं।\nकोई भी घड़ियाँ नदियाँ नहीं है।\nनिष्कर्ष:\nI. कुछ नदियाँ घड़ियाँ हैं।\nII. सभी नदियाँ पेन हैं।", "oh": ["न I सही है, न II", "केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है", "I और II दोनों सही हैं"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Rohit starts from point P, walks 8 km towards South, then turns right and walks 2 km, then turns left and walks 15 km. In which direction is Rohit now with respect to point P?", "o": ["North-East", "West", "North", "South-West"], "a": 3, "e": "Net East–West = -2 km, net North–South = -23 km; direction = South-West.", "qh": "रोहित बिंदु P से शुरू करके दक्षिण की ओर 8 km चलता है, फिर दाएँ मुड़कर 2 km चलता है, फिर बाएँ मुड़कर 15 km चलता है। अब रोहित बिंदु P से किस दिशा में है?", "oh": ["उत्तर-पूर्व", "पश्चिम", "उत्तर", "दक्षिण-पश्चिम"], "eh": "कुल पूर्व–पश्चिम = -2 km, कुल उत्तर–दक्षिण = -23 km; दिशा = दक्षिण-पश्चिम।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Which letter is 5th to the left of the 5th letter from the right end of the English alphabet?", "o": ["R", "P", "Q", "S"], "a": 2, "e": "5th from right = V (position 22); 5 to its left = position 17 = Q.", "qh": "अंग्रेज़ी वर्णमाला में दाएँ छोर से 5वें अक्षर के बाएँ 5वाँ अक्षर कौन-सा है?", "oh": ["R", "P", "Q", "S"], "eh": "दाएँ से 5वाँ = V (स्थान 22); उसके बाएँ 5वाँ = स्थान 17 = Q।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nGEZ, IDX, KCV, MBT, ?", "o": ["PAR", "OAR", "OZR", "OAT"], "a": 1, "e": "Letter positions move by +2, −1, −2 (for 1st, 2nd, 3rd letters). So ? = OAR.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nGEZ, IDX, KCV, MBT, ?", "oh": ["PAR", "OAR", "OZR", "OAT"], "eh": "अक्षरों की स्थिति +2, −1, −2 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = OAR।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: Mobile phones are not allowed inside the examination hall.\nConclusions:\nI. Candidates can keep their phones in their pockets inside the hall.\nII. Candidates may have to leave their phones outside the hall.", "o": ["Only conclusion II follows", "Only conclusion I follows", "Both I and II follow", "Neither I nor II follows"], "a": 0, "e": "Phones are not allowed inside, so I is false and II follows.", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: परीक्षा हॉल के अंदर मोबाइल फ़ोन ले जाने की अनुमति नहीं है।\nनिष्कर्ष:\nI. उम्मीदवार हॉल के अंदर फ़ोन जेब में रख सकते हैं।\nII. उम्मीदवारों को फ़ोन हॉल के बाहर छोड़ने पड़ सकते हैं।", "oh": ["केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है", "I और II दोनों सही हैं", "न I सही है, न II"], "eh": "अंदर फ़ोन की अनुमति नहीं, इसलिए I गलत और II सही।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["73", "59", "57", "47"], "a": 2, "e": "All except 57 are prime numbers.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["73", "59", "57", "47"], "eh": "57 को छोड़कर सभी अभाज्य संख्याएँ हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nSilk : Silkworm :: Honey : ?", "o": ["Flower", "Bee", "Sugar", "Hive"], "a": 1, "e": "Relation: 'obtained from'. Silk – Silkworm, so Honey – Bee.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nरेशम : रेशम का कीड़ा :: शहद : ?", "oh": ["फूल", "मधुमक्खी", "चीनी", "छत्ता"], "eh": "संबंध: 'से मिलता है'। रेशम – रेशम का कीड़ा, इसलिए शहद – मधुमक्खी।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "If 16 February 2024 was a Friday, what day of the week was 9 April 2025?", "o": ["Thursday", "Wednesday", "Tuesday", "Friday"], "a": 1, "e": "Days from 16 February 2024 to 9 April 2025 = 418. 418 = 7 × 59 + 5 → 5 odd day(s) after Friday = Wednesday.", "qh": "अगर 16 फ़रवरी 2024 को शुक्रवार था, तो 9 अप्रैल 2025 को कौन-सा दिन था?", "oh": ["गुरुवार", "बुधवार", "मंगलवार", "शुक्रवार"], "eh": "16 फ़रवरी 2024 से 9 अप्रैल 2025 तक दिन = 418। 418 = 7 × 59 + 5 → शुक्रवार के 5 दिन बाद = बुधवार।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n4 % F 9 % 1 N J $ 7 O 9 6 P 9 6 N L\nHow many symbols are there in the arrangement, each of which is immediately preceded by a number?", "o": ["5", "4", "2", "3"], "a": 2, "e": "Matching places: 4%F, 9%1 → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n4 % F 9 % 1 N J $ 7 O 9 6 P 9 6 N L\nइस क्रम में ऐसे कितने चिह्न हैं, जिनके ठीक पहले एक संख्या है?", "oh": ["5", "4", "2", "3"], "eh": "शर्त पूरी करने वाले स्थान: 4%F, 9%1 → 2।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'LADDER' is written as 'OXGAHO'. How will 'JACKET' be written in that language?", "o": ["XMFHHQ", "MDFNHW", "MXFHHP", "MXFHHQ"], "a": 3, "e": "Rule: letters move +3, -3 alternately. Applying it to JACKET gives MXFHHQ.", "qh": "एक कोड भाषा में 'LADDER' को 'OXGAHO' लिखा जाता है। उसी भाषा में 'JACKET' को कैसे लिखा जाएगा?", "oh": ["XMFHHQ", "MDFNHW", "MXFHHP", "MXFHHQ"], "eh": "नियम: अक्षर बारी-बारी से +3, -3 खिसकते हैं। JACKET पर लगाने से MXFHHQ मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'old road sun' is written as 'pu ni gu',\n'new old blue' is written as 'su pu ra',\n'road hot new' is written as 'su ki gu',\nWhat is the code for 'old'?", "o": ["gu", "ni", "pu", "su"], "a": 2, "e": "Compare the sentences: common words and common codes match. This gives 'old' = 'pu'.", "qh": "एक कोड भाषा में:\n'old road sun' को 'pu ni gu' लिखा जाता है,\n'new old blue' को 'su pu ra' लिखा जाता है,\n'road hot new' को 'su ki gu' लिखा जाता है,\n'old' का कोड क्या है?", "oh": ["gu", "ni", "pu", "su"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'old' = 'pu' मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n8, 13, 19, 26, 34, 43, ?", "o": ["56", "55", "53", "51"], "a": 2, "e": "Rule: Differences are 5, 6, 7, 8, 9, 10 (increase by 1). So ? = 53.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n8, 13, 19, 26, 34, 43, ?", "oh": ["56", "55", "53", "51"], "eh": "नियम: अंतर 5, 6, 7, 8, 9, 10 हैं (हर बार 1 बढ़ता है)। इसलिए ? = 53।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n12 : 252 :: 32 : ?", "o": ["768", "736", "737", "704"], "a": 1, "e": "Rule: x → x × (x with digits reversed). 12 → 252, so 32 → 736.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n12 : 252 :: 32 : ?", "oh": ["768", "736", "737", "704"], "eh": "नियम: x → x × (x के अंक उलटे)। 12 → 252, इसलिए 32 → 736।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "V, L, R, M, B and D are sitting around a circular table, all facing the centre.\nV sits second to the left of B.\nR sits second to the right of M.\nM is not an immediate neighbour of D.\nD is not an immediate neighbour of R.\nB sits immediately to the left of R.\nWho sits to the immediate right of D?", "o": ["V", "M", "L", "B"], "a": 0, "e": "Only one arrangement fits. Going to the right (anticlockwise) from D: D → V → M → B → R → L. Answer: V.", "qh": "V, L, R, M, B और D एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nV, B के बाईं ओर दूसरे स्थान पर बैठा है।\nR, M के दाईं ओर दूसरे स्थान पर बैठा है।\nM, D का ठीक पड़ोसी नहीं है।\nD, R का ठीक पड़ोसी नहीं है।\nB, R के ठीक बाईं ओर बैठा है।\nD के ठीक दाईं ओर कौन बैठा है?", "oh": ["V", "M", "L", "B"], "eh": "केवल एक व्यवस्था बैठती है। D से दाईं ओर (घड़ी की उलटी दिशा में) चलें: D → V → M → B → R → L। उत्तर: V।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "P, V, Q, W, C, M, T and E are sitting around a circular table, all facing the centre.\nV sits opposite Q.\nE sits immediately to the left of Q.\nC sits second to the right of M.\nW sits second to the right of Q.\nV sits second to the left of T.\nE sits second to the right of C.\nWho sits opposite M?", "o": ["E", "W", "V", "T"], "a": 0, "e": "Only one arrangement fits. Going to the right (anticlockwise) from M: M → V → C → T → E → Q → P → W. Answer: E.", "qh": "P, V, Q, W, C, M, T और E एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nV, Q के ठीक सामने बैठा है।\nE, Q के ठीक बाईं ओर बैठा है।\nC, M के दाईं ओर दूसरे स्थान पर बैठा है।\nW, Q के दाईं ओर दूसरे स्थान पर बैठा है।\nV, T के बाईं ओर दूसरे स्थान पर बैठा है।\nE, C के दाईं ओर दूसरे स्थान पर बैठा है।\nM के ठीक सामने कौन बैठा है?", "oh": ["E", "W", "V", "T"], "eh": "केवल एक व्यवस्था बैठती है। M से दाईं ओर (घड़ी की उलटी दिशा में) चलें: M → V → C → T → E → Q → P → W। उत्तर: E।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "Which two mathematical signs should be interchanged to make the following equation correct?\n9 − 9 ÷ 9 × 19 + 5 = 23", "o": ["− and ×", "+ and ÷", "+ and ×", "+ and −"], "a": 3, "e": "Interchanging + and −: 9 + 9 ÷ 9 × 19 − 5 = 23. ✔", "qh": "नीचे दिए समीकरण को सही बनाने के लिए किन दो गणितीय चिह्नों को आपस में बदलना होगा?\n9 − 9 ÷ 9 × 19 + 5 = 23", "oh": ["− और ×", "+ और ÷", "+ और ×", "+ और −"], "eh": "+ और − बदलने पर: 9 + 9 ÷ 9 × 19 − 5 = 23। ✔", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nBDT : CER :: MND : ?", "o": ["BON", "LMF", "NOB", "NOC"], "a": 2, "e": "Each letter moves +1, +1, -2 in order. MND → NOB.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nBDT : CER :: MND : ?", "oh": ["BON", "LMF", "NOB", "NOC"], "eh": "हर अक्षर क्रम से +1, +1, -2 खिसकता है। MND → NOB।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n738   791   568   132   489\nIf 1 is added to each digit of every number (9 becomes 0), how many of the new numbers will be even?", "o": ["3", "2", "0", "1"], "a": 1, "e": "New numbers: 849, 802, 679, 243, 590 → even ones = 2.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n738   791   568   132   489\nअगर हर संख्या के हर अंक में 1 जोड़ा जाए (9 का 0 हो जाए), तो नई संख्याओं में से कितनी सम होंगी?", "oh": ["3", "2", "0", "1"], "eh": "नई संख्याएँ: 849, 802, 679, 243, 590 → सम संख्याएँ = 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nCF, EH, GJ, IL, ?", "o": ["KN", "KM", "MN", "LN"], "a": 0, "e": "Letter positions move by +2, +2 (for 1st, 2nd letters). So ? = KN.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nCF, EH, GJ, IL, ?", "oh": ["KN", "KM", "MN", "LN"], "eh": "अक्षरों की स्थिति +2, +2 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = KN।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nC36Z, F49W, I64T, L81Q, ?", "o": ["O102N", "O100N", "O100O", "N100M"], "a": 1, "e": "First letter +3; number: consecutive squares; last letter -3. So ? = O100N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nC36Z, F49W, I64T, L81Q, ?", "oh": ["O102N", "O100N", "O100O", "N100M"], "eh": "पहला अक्षर +3; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -3। इसलिए ? = O100N।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["DFG", "JLM", "PQR", "QST"], "a": 2, "e": "In DFG, JLM, QST the gaps are +2, +1; in PQR they are +1, +1.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["DFG", "JLM", "PQR", "QST"], "eh": "DFG, JLM, QST में अंतर +2, +1 है; PQR में +1, +1 है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "Pointing to a photograph, a man said, \"This person is the son of the only son of my father.\" How is the person in the photograph related to the man?", "o": ["Son", "Nephew", "Brother", "Grandson"], "a": 0, "e": "Simplify from the end: 'the son of the only son of my father' points to the man's son.", "qh": "एक तस्वीर की ओर इशारा करते हुए एक आदमी ने कहा, \"यह व्यक्ति मेरे पिता के इकलौते बेटे का बेटा है।\" तस्वीर वाला व्यक्ति उस आदमी का क्या लगता है?", "oh": ["बेटा", "भतीजा", "भाई", "पोता"], "eh": "आखिर से सरल करें: 'मेरे पिता के इकलौते बेटे का बेटा' = बेटा।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "Who appoints the Governor of a state in India?", "o": ["The Prime Minister", "The Chief Minister", "The Chief Justice of India", "The President"], "a": 3, "e": "Under Article 155, the Governor is appointed by the President.", "qh": "भारत में किसी राज्य के राज्यपाल की नियुक्ति कौन करता है?", "oh": ["प्रधानमंत्री", "मुख्यमंत्री", "भारत के मुख्य न्यायाधीश", "राष्ट्रपति"], "eh": "अनुच्छेद 155 के अनुसार राज्यपाल की नियुक्ति राष्ट्रपति करते हैं।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Science & Tech", "q": "What does 'NavIC', India's regional navigation system, stand for?", "o": ["National Vehicle Integrated Control", "Naval Indian Communication", "Navigation with Indian Constellation", "Navigation via Indian Cable"], "a": 2, "e": "NavIC = Navigation with Indian Constellation, run by ISRO.", "qh": "भारत की क्षेत्रीय नेविगेशन प्रणाली 'NavIC' का पूरा नाम क्या है?", "oh": ["National Vehicle Integrated Control", "Naval Indian Communication", "Navigation with Indian Constellation", "Navigation via Indian Cable"], "eh": "NavIC = Navigation with Indian Constellation, जिसे इसरो चलाता है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "NABARD, the apex bank for agriculture and rural development, has its headquarters in:", "o": ["New Delhi", "Lucknow", "Hyderabad", "Mumbai"], "a": 3, "e": "NABARD (set up in 1982) is headquartered in Mumbai.", "qh": "कृषि और ग्रामीण विकास के शीर्ष बैंक नाबार्ड (NABARD) का मुख्यालय कहाँ है?", "oh": ["नई दिल्ली", "लखनऊ", "हैदराबाद", "मुंबई"], "eh": "1982 में बना नाबार्ड मुंबई में है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Which country won the men's FIH Hockey World Cup 2026, held in Belgium and the Netherlands?", "o": ["Spain", "Netherlands", "Belgium", "Germany"], "a": 3, "e": "Germany beat Spain 1–0 in the final at Wavre on 30 August 2026 to retain the title.", "qh": "बेल्जियम और नीदरलैंड में हुआ पुरुष FIH हॉकी विश्व कप 2026 किस देश ने जीता?", "oh": ["स्पेन", "नीदरलैंड", "बेल्जियम", "जर्मनी"], "eh": "30 अगस्त 2026 को वावरे में फ़ाइनल में जर्मनी ने स्पेन को 1–0 से हराकर खिताब बचाया।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Which country won the Uber Cup 2026 (women's badminton team championship)?", "o": ["South Korea", "China", "Japan", "Indonesia"], "a": 0, "e": "South Korea beat China 3–1 in the final at Horsens, Denmark.", "qh": "उबर कप 2026 (महिला बैडमिंटन टीम चैंपियनशिप) किस देश ने जीता?", "oh": ["दक्षिण कोरिया", "चीन", "जापान", "इंडोनेशिया"], "eh": "डेनमार्क के हॉर्सेंस में फ़ाइनल में दक्षिण कोरिया ने चीन को 3–1 से हराया।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "At the 2026 Winter Paralympics held in Italy (6–15 March), which nation won the most medals?", "o": ["United States", "China", "Italy", "Norway"], "a": 1, "e": "China topped the Winter Paralympics table for the second Games in a row with 44 medals (15 gold).", "qh": "मिलानो कोर्टिना 2026 शीतकालीन पैरालंपिक की पदक तालिका में कौन-सा देश सबसे ऊपर रहा?", "oh": ["अमेरिका", "चीन", "इटली", "नॉर्वे"], "eh": "चीन लगातार दूसरी बार 44 पदकों (15 स्वर्ण) के साथ शीतकालीन पैरालंपिक की तालिका में सबसे ऊपर रहा।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Awards", "q": "The Dadasaheb Phalke Award is given for outstanding contribution to:", "o": ["Literature", "Classical music", "Sports", "Indian cinema"], "a": 3, "e": "It is India's highest award in cinema, given at the National Film Awards.", "qh": "दादासाहेब फाल्के पुरस्कार किस क्षेत्र में खास योगदान के लिए दिया जाता है?", "oh": ["साहित्य", "शास्त्रीय संगीत", "खेल", "भारतीय सिनेमा"], "eh": "यह सिनेमा का भारत का सबसे बड़ा पुरस्कार है, जो राष्ट्रीय फ़िल्म पुरस्कारों में दिया जाता है।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Computer", "q": "Which of the following is NOT an operating system?", "o": ["Linux", "Windows", "Android", "MS Word"], "a": 3, "e": "MS Word is a word-processing application; the others are operating systems.", "qh": "इनमें से कौन-सा ऑपरेटिंग सिस्टम नहीं है?", "oh": ["लिनक्स", "विंडोज़", "एंड्रॉइड", "MS Word"], "eh": "MS Word शब्द-संसाधन (वर्ड प्रोसेसिंग) का सॉफ़्टवेयर है; बाकी ऑपरेटिंग सिस्टम हैं।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Who won the Nobel Prize in Literature 2026?", "o": ["Han Kang", "László Krasznahorkai", "Anne Carson", "Annie Ernaux"], "a": 2, "e": "Canadian poet Anne Carson won the 2026 Literature Nobel. (Han Kang won in 2024, Krasznahorkai in 2025, Ernaux in 2022.)", "qh": "साहित्य का नोबेल पुरस्कार 2026 किसे मिला?", "oh": ["हान कांग", "लास्लो क्रास्नाहोरकाई", "ऐन कार्सन", "एनी एर्नो"], "eh": "कनाडा की कवयित्री ऐन कार्सन को 2026 का साहित्य नोबेल मिला। (हान कांग 2024, क्रास्नाहोरकाई 2025, एर्नो 2022।)", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Who was named Player of the Match in the final of the ICC Men's T20 World Cup 2026?", "o": ["Suryakumar Yadav", "Jasprit Bumrah", "Hardik Pandya", "Axar Patel"], "a": 1, "e": "Jasprit Bumrah was Player of the Match as India beat New Zealand by 96 runs on 8 March 2026.", "qh": "ICC पुरुष T20 विश्व कप 2026 के फ़ाइनल में 'प्लेयर ऑफ़ द मैच' किसे चुना गया?", "oh": ["सूर्यकुमार यादव", "जसप्रीत बुमराह", "हार्दिक पांड्या", "अक्षर पटेल"], "eh": "8 मार्च 2026 को भारत की 96 रन की जीत में जसप्रीत बुमराह प्लेयर ऑफ़ द मैच रहे।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "History", "q": "Who founded the 'Azad Hind' Provisional Government in Singapore in October 1943?", "o": ["Subhas Chandra Bose", "Rash Behari Bose", "Mohan Singh", "Lala Har Dayal"], "a": 0, "e": "Netaji Subhas Chandra Bose proclaimed the Provisional Government of Free India in Singapore on 21 October 1943.", "qh": "अक्टूबर 1943 में सिंगापुर में 'आज़ाद हिंद' अस्थायी सरकार किसने बनाई?", "oh": ["सुभाष चंद्र बोस", "रासबिहारी बोस", "मोहन सिंह", "लाला हरदयाल"], "eh": "नेताजी सुभाष चंद्र बोस ने 21 अक्टूबर 1943 को सिंगापुर में आज़ाद हिंद की अस्थायी सरकार की घोषणा की।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "How many gold medals did India win at the 2026 Asian Games in Aichi-Nagoya?", "o": ["28", "21", "16", "25"], "a": 1, "e": "India won 85 medals including 21 gold and finished fourth. (India won 28 gold at Hangzhou 2023.)", "qh": "2026 के आइची-नागोया एशियाई खेलों में भारत ने कितने स्वर्ण पदक जीते?", "oh": ["28", "21", "16", "25"], "eh": "भारत ने 21 स्वर्ण समेत 85 पदक जीते और चौथे स्थान पर रहा। (हांगझोउ 2023 में भारत ने 28 स्वर्ण जीते थे।)", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Art & Culture", "q": "Garba, danced in circles during Navratri, is mainly associated with:", "o": ["Rajasthan", "Punjab", "Maharashtra", "Gujarat"], "a": 3, "e": "Garba, danced in circles during Navratri, comes from Gujarat.", "qh": "गरबा किस राज्य का लोकनृत्य है?", "oh": ["राजस्थान", "पंजाब", "महाराष्ट्र", "गुजरात"], "eh": "नवरात्रि में गोल घेरे में किया जाने वाला गरबा गुजरात का है।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "Who chairs the GST Council?", "o": ["The Prime Minister", "The RBI Governor", "The President", "The Union Finance Minister"], "a": 3, "e": "Under Article 279A, the Union Finance Minister is the Chairperson of the GST Council.", "qh": "GST परिषद की अध्यक्षता कौन करता है?", "oh": ["प्रधानमंत्री", "RBI गवर्नर", "राष्ट्रपति", "केंद्रीय वित्त मंत्री"], "eh": "अनुच्छेद 279A के अनुसार केंद्रीय वित्त मंत्री GST परिषद के अध्यक्ष होते हैं।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Which former Chief Minister of Kerala was conferred the Padma Vibhushan posthumously in 2026?", "o": ["Oommen Chandy", "E. K. Nayanar", "V. S. Achuthanandan", "K. Karunakaran"], "a": 2, "e": "V. S. Achuthanandan was named for the Padma Vibhushan (posthumous, public affairs) on 25 January 2026.", "qh": "केरल के किस पूर्व मुख्यमंत्री को 2026 में मरणोपरांत पद्म विभूषण दिया गया?", "oh": ["ओमन चांडी", "ई. के. नयनार", "वी. एस. अच्युतानंदन", "के. करुणाकरन"], "eh": "25 जनवरी 2026 को वी. एस. अच्युतानंदन को (सार्वजनिक कार्य के लिए) मरणोपरांत पद्म विभूषण घोषित हुआ।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "How many medals did India win at the Aichi-Nagoya 2026 Asian Para Games, its best-ever haul?", "o": ["108", "111", "85", "114"], "a": 3, "e": "India won 114 medals (30 gold, 35 silver, 49 bronze) at the Asian Para Games (18–24 October 2026) and finished fourth.", "qh": "आइची-नागोया 2026 एशियाई पैरा खेलों में भारत ने अपने अब तक के सबसे ज़्यादा कितने पदक जीते?", "oh": ["108", "111", "85", "114"], "eh": "एशियाई पैरा खेलों (18–24 अक्टूबर 2026) में भारत ने 114 पदक (30 स्वर्ण, 35 रजत, 49 कांस्य) जीते और चौथे स्थान पर रहा।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "Which is the largest public sector bank in India?", "o": ["State Bank of India", "Punjab National Bank", "Bank of Baroda", "Canara Bank"], "a": 0, "e": "SBI is India's largest public sector bank by assets, deposits and branches.", "qh": "भारत का सबसे बड़ा सरकारी (सार्वजनिक क्षेत्र का) बैंक कौन-सा है?", "oh": ["भारतीय स्टेट बैंक", "पंजाब नेशनल बैंक", "बैंक ऑफ़ बड़ौदा", "केनरा बैंक"], "eh": "संपत्ति, जमा और शाखाओं में SBI भारत का सबसे बड़ा सरकारी बैंक है।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "On which surface is the Wimbledon tennis tournament played?", "o": ["Grass", "Clay", "Hard court", "Carpet"], "a": 0, "e": "Wimbledon is the only Grand Slam played on grass.", "qh": "विंबलडन टेनिस टूर्नामेंट किस सतह पर खेला जाता है?", "oh": ["घास", "मिट्टी (क्ले)", "हार्ड कोर्ट", "कारपेट"], "eh": "विंबलडन घास पर खेला जाने वाला एकमात्र ग्रैंड स्लैम है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Awards", "q": "In which year was the Bharat Ratna first awarded?", "o": ["1950", "1954", "1947", "1962"], "a": 1, "e": "The Bharat Ratna was instituted and first awarded in 1954.", "qh": "भारत रत्न पहली बार किस साल दिया गया?", "oh": ["1950", "1954", "1947", "1962"], "eh": "भारत रत्न 1954 में शुरू हुआ और पहली बार उसी साल दिया गया।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Who won the men's singles title at Wimbledon 2026?", "o": ["Jannik Sinner", "Carlos Alcaraz", "Novak Djokovic", "Alexander Zverev"], "a": 0, "e": "Jannik Sinner retained his Wimbledon title by beating Alexander Zverev in the final.", "qh": "विंबलडन 2026 में पुरुष एकल खिताब किसने जीता?", "oh": ["यानिक सिनर", "कार्लोस अल्कराज़", "नोवाक जोकोविच", "अलेक्ज़ेंडर ज़्वेरेव"], "eh": "यानिक सिनर ने फ़ाइनल में अलेक्ज़ेंडर ज़्वेरेव को हराकर विंबलडन खिताब बचाया।", "level": "medium"}]});
